import AVFoundation
import Combine

@MainActor
final class PlayerViewModel: ObservableObject {
    @Published private(set) var progress: Double = 0
    @Published private(set) var isPlaying = false
    @Published var volume: Float = 0.8

    private let player = AVPlayer()
    private var progressTimer: Timer?
    private var cancellables = Set<AnyCancellable>()

    init() {
        $volume
            .removeDuplicates()
            .sink { [weak self] value in self?.player.volume = value }
            .store(in: &cancellables)
    }

    func play(_ item: AVPlayerItem) {
        player.replaceCurrentItem(with: item)
        player.play()
        isPlaying = true
        progressTimer?.invalidate()
        progressTimer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { _ in
            MainActor.assumeIsolated {
                self.updateProgress()
            }
        }
    }

    func pause() {
        player.pause()
        isPlaying = false
    }

    private func updateProgress() {
        guard let item = player.currentItem, item.duration.seconds.isFinite, item.duration.seconds > 0 else { return }
        progress = player.currentTime().seconds / item.duration.seconds
    }
}

