import Foundation

actor SyncService {
    private var lastSync: Date?
    private var pendingChanges: [Change] = []
    private let api: SyncAPI

    init(api: SyncAPI) {
        self.api = api
    }

    func enqueue(_ change: Change) {
        pendingChanges.append(change)
    }

    func sync() async throws -> Int {
        let batch = pendingChanges
        guard !batch.isEmpty else { return 0 }
        try await api.push(batch, since: lastSync)
        pendingChanges.removeFirst(batch.count)
        lastSync = .now
        return batch.count
    }

    /// Wraps the legacy callback-based conflict resolver, which calls its completion exactly once.
    nonisolated func resolveConflicts(for ids: [Change.ID], using resolver: LegacyConflictResolver) async throws -> [Resolution] {
        try await withCheckedThrowingContinuation { continuation in
            resolver.resolve(ids: ids) { result in
                switch result {
                case .success(let resolutions):
                    continuation.resume(returning: resolutions)
                case .failure(let error):
                    continuation.resume(throwing: error)
                }
            }
        }
    }
}

