import Foundation

final class DownloadManager: NSObject, URLSessionDownloadDelegate {
    static let shared = DownloadManager()

    private(set) var progressByURL: [URL: Double] = [:]
    private var completions: [URL: (Result<URL, Error>) -> Void] = [:]
    private lazy var session = URLSession(
        configuration: .background(withIdentifier: "com.example.downloads"),
        delegate: self,
        delegateQueue: nil
    )

    func download(_ url: URL, completion: @escaping (Result<URL, Error>) -> Void) {
        completions[url] = completion
        progressByURL[url] = 0
        session.downloadTask(with: url).resume()
    }

    func urlSession(_ session: URLSession, downloadTask: URLSessionDownloadTask, didWriteData bytesWritten: Int64,
                    totalBytesWritten: Int64, totalBytesExpectedToWrite: Int64) {
        guard let url = downloadTask.originalRequest?.url, totalBytesExpectedToWrite > 0 else { return }
        progressByURL[url] = Double(totalBytesWritten) / Double(totalBytesExpectedToWrite)
    }

    func urlSession(_ session: URLSession, downloadTask: URLSessionDownloadTask, didFinishDownloadingTo location: URL) {
        guard let url = downloadTask.originalRequest?.url else { return }
        progressByURL[url] = nil
        completions.removeValue(forKey: url)?(.success(location))
    }

    func urlSession(_ session: URLSession, task: URLSessionTask, didCompleteWithError error: Error?) {
        guard let error, let url = task.originalRequest?.url else { return }
        progressByURL[url] = nil
        completions.removeValue(forKey: url)?(.failure(error))
    }
}

