import UIKit

actor ImagePipeline {
    static let shared = ImagePipeline()

    private var cache: [URL: UIImage] = [:]
    private var tasks: [URL: Task<UIImage, Error>] = [:]

    func image(for url: URL) async throws -> UIImage {
        if let cached = cache[url] { return cached }
        if let existing = tasks[url] { return try await existing.value }

        let task = Task<UIImage, Error> {
            let (data, _) = try await URLSession.shared.data(from: url)
            guard let image = await Self.decode(data) else { throw URLError(.cannotDecodeContentData) }
            return image
        }
        tasks[url] = task
        defer { tasks[url] = nil }
        let image = try await task.value
        cache[url] = image
        return image
    }

    private static func decode(_ data: Data) async -> UIImage? {
        guard let image = UIImage(data: data) else { return nil }
        return await withCheckedContinuation { continuation in
            image.prepareForDisplay { prepared in
                continuation.resume(returning: prepared)
            }
        }
    }
}

