import Combine
import Foundation

@MainActor
final class CartViewModel: ObservableObject {
    @Published private(set) var items: [CartItem] = []
    @Published private(set) var subtotal: Decimal = 0
    @Published var promoCode = ""
    @Published private(set) var promoMessage: String?

    private let cartService: CartService
    private var cancellables = Set<AnyCancellable>()

    init(cartService: CartService) {
        self.cartService = cartService

        $items
            .map { $0.reduce(Decimal.zero) { $0 + $1.price * Decimal($1.quantity) } }
            .assign(to: &$subtotal)

        $promoCode
            .debounce(for: .milliseconds(400), scheduler: RunLoop.main)
            .removeDuplicates()
            .filter { !$0.isEmpty }
            .sink { [weak self] code in
                Task { await self?.validatePromo(code) }
            }
            .store(in: &cancellables)
    }

    func load() async {
        items = (try? await cartService.fetchCart()) ?? []
    }

    func updateQuantity(of itemID: CartItem.ID, to quantity: Int) async {
        guard let index = items.firstIndex(where: { $0.id == itemID }) else { return }
        items[index].quantity = max(0, quantity)
        if items[index].quantity == 0 { items.remove(at: index) }
        try? await cartService.save(items)
    }

    private func validatePromo(_ code: String) async {
        do {
            let result = try await cartService.validatePromo(code)
            promoMessage = result.message
        } catch {
            promoMessage = "That code isn't valid"
        }
    }
}

