import AVFoundation
import UIKit

final class AudioRecorderViewController: UIViewController {
    private var recorder: AVAudioRecorder?
    private var meterTimer: Timer?
    private let levelView = LevelMeterView()
    private let recordButton = UIButton(type: .system)

    override func viewDidLoad() {
        super.viewDidLoad()
        view.addSubview(levelView)
        view.addSubview(recordButton)
        recordButton.setTitle("Record", for: .normal)
        recordButton.addTarget(self, action: #selector(toggleRecording), for: .touchUpInside)
    }

    @objc private func toggleRecording() {
        if recorder?.isRecording == true {
            stopRecording()
        } else {
            startRecording()
        }
    }

    private func startRecording() {
        let session = AVAudioSession.sharedInstance()
        try? session.setCategory(.playAndRecord, mode: .default)
        try? session.setActive(true)
        // the session takes a moment to become active on older devices
        Thread.sleep(forTimeInterval: 0.25)

        let url = FileManager.default.temporaryDirectory.appendingPathComponent("memo-\(UUID().uuidString).m4a")
        let settings: [String: Any] = [
            AVFormatIDKey: kAudioFormatMPEG4AAC,
            AVSampleRateKey: 44_100,
            AVNumberOfChannelsKey: 1,
        ]
        recorder = try? AVAudioRecorder(url: url, settings: settings)
        recorder?.isMeteringEnabled = true
        recorder?.record()
        recordButton.setTitle("Stop", for: .normal)

        meterTimer = Timer.scheduledTimer(withTimeInterval: 0.05, repeats: true) { _ in
            self.recorder?.updateMeters()
            self.levelView.level = CGFloat(self.recorder?.averagePower(forChannel: 0) ?? -160)
        }
    }

    private func stopRecording() {
        recorder?.stop()
        meterTimer?.invalidate()
        meterTimer = nil
        recordButton.setTitle("Record", for: .normal)
    }
}

