import Foundation

final class InventoryCache: @unchecked Sendable {
    static let shared = InventoryCache()

    private let lock = NSLock()
    private var stockBySKU: [String: Int] = [:]
    private var lastRefresh: Date?

    func stock(for sku: String) -> Int? {
        lock.withLock { stockBySKU[sku] }
    }

    func apply(_ updates: [String: Int]) {
        lock.withLock {
            stockBySKU.merge(updates) { _, new in new }
            lastRefresh = Date()
        }
    }

    func refreshInBackground(using client: InventoryClient, completion: @escaping (Bool) -> Void) {
        DispatchQueue.global(qos: .utility).async {
            client.fetchAll { result in
                switch result {
                case .success(let updates):
                    self.apply(updates)
                    DispatchQueue.main.async { completion(true) }
                case .failure:
                    DispatchQueue.main.async { completion(false) }
                }
            }
        }
    }
}

