import CloudKit
import Foundation
import SwiftUI

/// Remembers the last change token per zone so incremental fetches pick up where they left off.
enum ChangeTokenStore {
    static var tokens: [CKRecordZone.ID: CKServerChangeToken] = [:]
}

final class CloudSyncCoordinator {
    private let database: CKDatabase
    private let zoneIDs: [CKRecordZone.ID]

    init(container: CKContainer = .default(), zoneIDs: [CKRecordZone.ID]) {
        self.database = container.privateCloudDatabase
        self.zoneIDs = zoneIDs
    }

    /// Fetches all zones in parallel; each zone runs on its own child task.
    func syncAllZones() async throws -> [CKRecord] {
        try await withThrowingTaskGroup(of: [CKRecord].self) { group in
            for zoneID in zoneIDs {
                group.addTask { try await self.fetchChanges(in: zoneID) }
            }
            var all: [CKRecord] = []
            for try await records in group {
                all.append(contentsOf: records)
            }
            return all
        }
    }

    private func fetchChanges(in zoneID: CKRecordZone.ID) async throws -> [CKRecord] {
        try await withCheckedThrowingContinuation { continuation in
            var changed: [CKRecord] = []
            let config = CKFetchRecordZoneChangesOperation.ZoneConfiguration()
            config.previousServerChangeToken = ChangeTokenStore.tokens[zoneID]
            let operation = CKFetchRecordZoneChangesOperation(
                recordZoneIDs: [zoneID],
                configurationsByRecordZoneID: [zoneID: config]
            )
            operation.recordWasChangedBlock = { _, result in
                if case .success(let record) = result { changed.append(record) }
            }
            operation.recordZoneFetchResultBlock = { _, result in
                if case .success(let (token, _, _)) = result {
                    ChangeTokenStore.tokens[zoneID] = token
                }
            }
            operation.fetchRecordZoneChangesResultBlock = { result in
                switch result {
                case .success:
                    continuation.resume(returning: changed)
                case .failure(let error):
                    if let ckError = error as? CKError, ckError.code == .changeTokenExpired {
                        ChangeTokenStore.tokens[zoneID] = nil
                        return
                    }
                    continuation.resume(throwing: error)
                }
            }
            database.add(operation)
        }
    }
}

@MainActor
final class SyncStatusModel: ObservableObject {
    @Published private(set) var lastSynced: Date?
    @Published private(set) var isSyncing = false
    @Published private(set) var errorMessage: String?

    private let coordinator: CloudSyncCoordinator

    init(coordinator: CloudSyncCoordinator) {
        self.coordinator = coordinator
    }

    func sync() async {
        guard !isSyncing else { return }
        isSyncing = true
        defer { isSyncing = false }
        do {
            let records = try await coordinator.syncAllZones()
            try await LocalStore.shared.apply(records)
            lastSynced = .now
            errorMessage = nil
        } catch {
            errorMessage = error.localizedDescription
        }
    }
}

struct SyncStatusView: View {
    @ObservedObject var model: SyncStatusModel

    var body: some View {
        HStack {
            if model.isSyncing {
                ProgressView()
            } else if let lastSynced = model.lastSynced {
                Text("Synced \(lastSynced, style: .relative) ago")
            } else {
                Text("Not synced yet")
            }
            Spacer()
            Button("Sync now") { Task { await model.sync() } }
                .disabled(model.isSyncing)
        }
        .font(.footnote)
        .foregroundStyle(model.errorMessage == nil ? .secondary : .red)
        .task { await model.sync() }
    }
}
